(7400083, 1164552, 38032, '<td valign="top">barf-worthy.</td>', 'barf-worthy.', '2015-08-26 11:36:47.000000', NULL, 1),
(7400084, 1164451, 38032, '<td valign="top">compelling. Love the tones and grit.. stacking this up there with the best in this challenge.</td>', 'compelling. Love the tones and grit.. stacking this up there with the best in this challenge.', '2015-08-26 11:37:37.000000', NULL, 1),
(7400085, 1164955, 38032, '<td valign="top">These are wonderful. Love the subtle HDR.</td>', 'These are wonderful. Love the subtle HDR.', '2015-08-26 11:38:21.000000', NULL, 1),
(7400089, 1164908, 38032, '<td valign="top">Oh my gosh this is too much. The composition, light, and story are dismal and perfect all at once. The raised shoes / heels, the leash, the stare at the phone ... she''s not accepting where she is. She needs love but cannot find it. The cat is there - but not for her. The warm, synthetic color adds to the unwelcoming urban atmosphere. The cakes form a facade of perfection and beauty - much like the banner of the old city. The lollipops, the food dish, carelessly stacked newspapers and debris on the right - the eye and mind travels everywhere and sees the truth behind the sadness of this thing we call life.<br/>Heartbreaking and nearly perfect all at once.  9.</td>', 'Oh my gosh this is too much. The composition, light, and story are dismal and perfect all at once. The raised shoes / heels, the leash, the stare at the phone ... she''s not accepting where she is. She needs love but cannot find it. The cat is there - but not for her. The warm, synthetic color adds to the unwelcoming urban atmosphere. The cakes form a facade of perfection and beauty - much like the banner of the old city. The lollipops, the food dish, carelessly stacked newspapers and debris on the right - the eye and mind travels everywhere and sees the truth behind the sadness of this thing we call life.Heartbreaking and nearly perfect all at once.  9.', '2015-08-26 11:49:11.000000', NULL, 1),
(7400111, 1164879, 101707, '<td valign="top">Too, too funny.</td>', 'Too, too funny.', '2015-08-26 12:56:18.000000', NULL, 1),
