(7401413, 1164930, 62249, '<td valign="top">Ink? Motor oil? Meets the criteria for the challenge and is a technically acceptable photo. Doesn''t tell much of a story.</td>', 'Ink? Motor oil? Meets the criteria for the challenge and is a technically acceptable photo. Doesn''t tell much of a story.', '2015-08-31 23:02:08.000000', NULL, 1),
(7401414, 1164591, 62249, '<td valign="top">Colorful and very sharp.</td>', 'Colorful and very sharp.', '2015-08-31 23:02:55.000000', NULL, 1),
(7401415, 1164716, 62249, '<td valign="top">Between the fish-eye lens and the overly crunchy processing, this actually *doesn''t* look like a very dirty scene. The high contrast, high structure, and extreme sharpening of the image kinda make things look cleaner than they might otherwise have appeared.</td>', 'Between the fish-eye lens and the overly crunchy processing, this actually *doesn''t* look like a very dirty scene. The high contrast, high structure, and extreme sharpening of the image kinda make things look cleaner than they might otherwise have appeared.', '2015-08-31 23:05:48.000000', NULL, 1),
(7401416, 1164879, 62249, '<td valign="top">This is a humorous take on the challenge.</td>', 'This is a humorous take on the challenge.', '2015-08-31 23:06:10.000000', NULL, 1),
(7401417, 1165022, 62249, '<td valign="top">Good tonal range on the shiny part (a bumper?). Could''ve used a bit more light in the cavity of the other object.</td>', 'Good tonal range on the shiny part (a bumper?). Could''ve used a bit more light in the cavity of the other object.', '2015-08-31 23:07:05.000000', NULL, 1),
