(7401650, 1164907, 108069, '<td valign="top">Beautifully framed. Love the lines. Intersections of linear shadows and irregularly shaped decay, two forgotten elements meet and get the spotlight. I would have over-processed the hell out of this so I am enjoying the subtle touch. Great sight.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155941" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg"/></a></td>', 'Beautifully framed. Love the lines. Intersections of linear shadows and irregularly shaped decay, two forgotten elements meet and get the spotlight. I would have over-processed the hell out of this so I am enjoying the subtle touch. Great sight. ', '2015-09-02 00:09:08.000000', NULL, 1),
(7401651, 1164462, 108069, '<td valign="top">Nice find and nicely captured. Separation of two worlds, and this guy decides on the dingier one.</td>', 'Nice find and nicely captured. Separation of two worlds, and this guy decides on the dingier one.', '2015-09-02 00:11:40.000000', NULL, 1),
(7401652, 1164405, 108069, '<td valign="top">Nice find. Creepy.</td>', 'Nice find. Creepy.', '2015-09-02 00:11:56.000000', NULL, 1),
(7401653, 1165022, 108069, '<td valign="top">Cool photo. Hope in a bumper.</td>', 'Cool photo. Hope in a bumper.', '2015-09-02 00:12:38.000000', NULL, 1),
(7401656, 1164979, 108069, '<td valign="top">I''m not entirely sure you haven''t broken into my cellar. I''m enjoying this framing. Concentric rectangles of alternating imperfection, bound by neglect. It''s a crazy thought, that this is all some of these creatures know. An entire life spent on the wrong side of a window. Born into prison.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155941" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg"/></a></td>', 'I''m not entirely sure you haven''t broken into my cellar. I''m enjoying this framing. Concentric rectangles of alternating imperfection, bound by neglect. It''s a crazy thought, that this is all some of these creatures know. An entire life spent on the wrong side of a window. Born into prison. ', '2015-09-02 00:23:43.000000', NULL, 1),
